gZk(){return"Verse Flow\n\u062a\u062c\u0631\u0628\u0629 \u0642\u0631\u0627\u0621\u0629 \u0639\u0635\u0631\u064a\u0629 \ud83d\udcda"},
gPW(){return"\u062a\u0635\u0645\u064a\u0645 \u0623\u0646\u064a\u0642 \u0648\u0628\u0633\u064a\u0637 \u0644\u062a\u0637\u0628\u064a\u0642 \u0642\u0627\u0631\u0626 \u0643\u062a\u0628 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0631\u0627\u062d\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629. \u064a\u062a\u0645\u064a\u0632 \u0628\u0648\u0627\u062c\u0647\u0629 \u062a\u0648\u0641\u0631 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u062d\u062c\u0645 \u0627\u0644\u0646\u0635\u060c \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0644\u064a\u0644\u064a/\u0627\u0644\u0646\u0647\u0627\u0631\u064a\u060c \u0627\u0646\u062a\u0642\u0627\u0644\u0627\u062a \u0633\u0644\u0633\u0629 \u0628\u064a\u0646 \u0627\u0644\u0635\u0641\u062d\u0627\u062a\u060c \u0648\u062a\u0635\u0645\u064a\u0645 \u0645\u0643\u062a\u0628\u0629 \u0623\u0646\u064a\u0642."},
gSv(){return"\u0644\u0648\u062d\u0629 \u0637\u0627\u0642\u0629"},
gre(){return"\u062a\u0635\u0648\u064a\u0631 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
gw0(){return"\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062f\u0627\u0643\u0646"},
gWK(){return"\u062a\u0637\u0628\u064a\u0642 \u062a\u062a\u0628\u0639 \u0627\u0644\u0637\u0627\u0642\u0629"},
gWM(){return"\u0628\u062f\u0627\u064a\u0629 \u0642\u0648\u064a\u0629\n\u062a\u062a\u0628\u0639 \u0630\u0643\u064a \u0644\u0623\u062d\u0645\u0627\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u26a1"},
gWL(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u062d\u062f\u064a\u062b\u0629 \u0648\u0628\u062f\u064a\u0647\u064a\u0629 \u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u062a\u0628\u0639 \u0627\u0644\u0623\u062d\u0645\u0627\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064a\u0629 \u0627\u0644\u0630\u0643\u064a\u0629. \u064a\u062a\u064a\u062d \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0627\u0633\u062a\u0647\u0644\u0627\u0643 \u0644\u062d\u0638\u064a\u064b\u0627\u060c \u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0639\u0644\u0649 \u062d\u062f\u0629\u060c \u0648\u0625\u0646\u0634\u0627\u0621 \u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0645\u062e\u0635\u0635\u0629 \u0639\u0646\u062f \u0648\u062c\u0648\u062f \u0623\u062d\u0645\u0627\u0644 \u0632\u0627\u0626\u062f\u0629."},
gTt(){return"\u0644\u0648\u062d\u0629 \u0645\u0627\u0644\u064a\u0629"},
gHr(){return"\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u0623\u0633\u0647\u0645"},
gSI(){return"\u0627\u0633\u062a\u0643\u0634\u0641 \u0627\u0644\u0645\u0632\u064a\u062f"},
gfi(){return"\u0627\u0644\u062a\u0627\u0644\u064a"},
gYE(){return"\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062a\u062f\u0627\u0648\u0644"},
gYG(){return"\u0630\u0643\u064a \u0648\u0628\u0633\u064a\u0637\n\u0645\u0646\u0635\u0629 \u062a\u062f\u0627\u0648\u0644 \u0627\u0644\u0623\u0633\u0647\u0645 \ud83d\udcc8"},
gYF(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0646\u0638\u064a\u0641 \u0648\u0628\u0633\u064a\u0637 \u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u062f\u0627\u0648\u0644 \u0627\u0644\u0623\u0633\u0647\u0645 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062d\u0627\u0641\u0638 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u064a\u0629. \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0639\u0631\u0636 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0633\u0648\u0642 \u0644\u062d\u0638\u064a\u064b\u0627\u060c \u0645\u062e\u0637\u0637\u0627\u062a \u062a\u0641\u0627\u0639\u0644\u064a\u0629\u060c \u0642\u0648\u0627\u0626\u0645 \u0645\u062a\u0627\u0628\u0639\u0629\u060c \u0648\u062a\u062c\u0631\u0628\u0629 \u062a\u0646\u0642\u0644 \u0633\u0644\u0633\u0629 \u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646 \u0648\u0627\u0644\u0645\u062d\u062a\u0631\u0641\u064a\u0646."},
