gRh(){return"\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0639\u0645\u064a\u0642"},
gCY(){return"\u0623\u0646\u0638\u0645\u0629 \u062f\u0639\u0645 \u0627\u0644\u0642\u0631\u0627\u0631"},
gXe(){return"\u0628\u0627\u064a\u062b\u0648\u0646 (Streamlit)"},
gYI(){return"\u062a\u0637\u0628\u064a\u0642 \u0648\u064a\u0628 \u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u062d\u0648\u0644\u0627\u062a"},
gOR(){return"\u0631\u0624\u0649 \u0645\u062f\u0639\u0648\u0645\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \n\u0644\u0625\u062a\u062e\u0627\u0630 \u0642\u0631\u0627\u0631\u0627\u062a \u0623\u0630\u0643\u0649 \ud83e\udde0"},
gOS(){return"\u062a\u0637\u0628\u064a\u0642 \u0648\u064a\u0628 \u0645\u0628\u0646\u064a \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Streamlit \u064a\u0633\u062a\u0641\u064a\u062f \u0645\u0646 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0622\u0644\u064a \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\ud83d\udcca\u060c \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u0646\u0645\u0627\u0637\ud83d\udcac\u060c \u0648\u062f\u0639\u0645 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0642\u0631\u0627\u0631\ud83e\udde0. \u064a\u062a\u0636\u0645\u0646 \u0645\u064a\u0632\u0627\u062a \u0645\u062b\u0644 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u062a\u0646\u0628\u0624\u064a\u0629\u060c \u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629\u060c \u0648\u0648\u0627\u062c\u0647\u0629 \u0645\u0633\u062a\u062e\u062f\u0645 \u0633\u0644\u0633\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0639\u0628\u0631 \u0627\u0644\u0623\u062c\u0647\u0632\u0629."},
gRc(){return"\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
gWO(){return"\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u062a\u0646\u0628\u0624\u064a\u0629"},
gPg(){return"\u0645\u0639\u0648\u0642\u0627\u062a \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0641\u064a \u062f\u0639\u0645 \u0627\u0644\u0642\u0631\u0627\u0631"},
gPi(){return"\u0645\u0639\u0648\u0642\u0627\u062a \u062a\u0642\u0646\u064a\u0629\u060c \u0628\u0634\u0631\u064a\u0629\u060c \u062a\u0646\u0638\u064a\u0645\u064a\u0629\u060c \u0645\u0627\u0644\u064a\u0629\u060c \u0648\u062e\u0627\u0631\u062c\u064a\u0629 \u2699\ufe0f"},
gPh(){return"\u062a\u0633\u0644\u0637 \u0647\u0630\u0647 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0636\u0648\u0621 \u0639\u0644\u0649 \u0623\u0628\u0631\u0632 \u0627\u0644\u0645\u0639\u0648\u0642\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0648\u0627\u062c\u0647 \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0641\u064a \u0623\u0646\u0638\u0645\u0629 \u062f\u0639\u0645 \u0627\u0644\u0642\u0631\u0627\u0631\u060c \u0628\u0645\u0627 \u064a\u0634\u0645\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u062a\u0642\u0646\u064a\u0629\u2699\ufe0f\u060c \u0627\u0644\u0628\u0634\u0631\u064a\u0629\ud83e\udde0\u060c \u0627\u0644\u062a\u0646\u0638\u064a\u0645\u064a\u0629\ud83c\udfe2\u060c \u0627\u0644\u0645\u0627\u0644\u064a\u0629\ud83d\udcb0\u060c \u0648\u0627\u0644\u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629\ud83c\udf10 \u0627\u0644\u062a\u064a \u062a\u0639\u064a\u0642 \u0627\u0644\u062a\u0646\u0641\u064a\u0630."},
gTR(){return"forSale | \u062f\u0644\u0651\u0646\u064a"},
gTQ(){return"\u0633\u0648\u0642 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 \u0641\u064a \u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0623\u0632\u0645\u0627\u062a"},
gTP(){return"\u0645\u0646\u0635\u0629 \u0628\u064a\u0639 \u0645\u062a\u0646\u0642\u0644\u0629 \u062a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u060c \u0645\u0635\u0645\u0645\u0629 \u0644\u0644\u0645\u062c\u062a\u0645\u0639\u0627\u062a \u062a\u062d\u062a \u0627\u0644\u0636\u063a\u0637\u060c \u062e\u0627\u0635\u0629 \u0641\u064a \u063a\u0632\u0629. \u064a\u0646\u0638\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f \u0627\u0644\u0637\u0627\u0631\u0626 \u0648\u0627\u0644\u0644\u0627\u0645\u0631\u0643\u0632\u064a \u0627\u0644\u0630\u064a \u064a\u0646\u0634\u0623 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0646\u0632\u0648\u062d\u2014\u064a\u0631\u0628\u0637 \u0628\u064a\u0646 \u0645\u0646 \u0644\u062f\u064a\u0647\u0645 \u0641\u0627\u0626\u0636 \u0645\u0646 \u0627\u0644\u0636\u0631\u0648\u0631\u064a\u0627\u062a (\u0623\u062c\u0647\u0632\u0629 \u0637\u0627\u0642\u0629\u060c \u062d\u0644\u064a\u0628 \u0623\u0637\u0641\u0627\u0644\u060c \u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0637\u0628\u064a\u0629) \u0648\u0645\u0646 \u0647\u0645 \u0641\u064a \u062d\u0627\u062c\u0629 \u0645\u0644\u062d\u0629. \u0627\u0644\u0645\u064a\u0632\u0627\u062a \u062a\u0634\u0645\u0644: \u0642\u0648\u0627\u0626\u0645 \u0645\u0648\u062b\u0642\u0629\u060c \u0645\u062d\u0627\u062f\u062b\u0629 \u0622\u0645\u0646\u0629\u060c \u0628\u062d\u062b \u062d\u0633\u0628 \u0627\u0644\u0645\u0648\u0642\u0639\u060c \u0648\u062a\u0635\u0645\u064a\u0645 \u064a\u0639\u0645\u0644 \u0628\u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0641\u064a \u0627\u0644\u0628\u064a\u0626\u0627\u062a \u0630\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u0645\u062d\u062f\u0648\u062f."},
gXs(){return"\u0645\u062d\u0627\u062f\u062b\u0629 \u0641\u0648\u0631\u064a\u0629"},
gFX(){return"\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u062c\u063a\u0631\u0627\u0641\u064a"},
gXa(){return"\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0641\u0648\u0631\u064a\u0629"},
gSs(){return"\u062a\u0634\u0641\u064a\u0631 \u0645\u0646 \u0637\u0631\u0641 \u0644\u0637\u0631\u0641"},
gW6(){return"\u062a\u0635\u0645\u064a\u0645 \u064a\u0639\u0645\u0644 \u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644"},
